407	     *
408	     * @param name to test
409	     * @return true if pet name is already in use
410	     */
411	    public Pet getPet(String name, boolean ignoreNew) {
412	        name = name.toLowerCase();
413	        for (Pet pet : getPetsInternal()) {
414	            if (!ignoreNew || !pet.isNew()) {
415	                String compName = pet.getName();
416	                compName = compName.toLowerCase();
417	                if (compName.equals(name)) {
418	                    return pet;
419	                }
420	            }
421	        }
422	        return null;
423	    }
424	
425	    public Pet getPet(Integer petId) {
426	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
427	    }
428	
429	    @Override
430	    public String toString() {
431	        return new ToStringCreator(this)
432	
433	            .append("id", this.getId())
434	            .append("new", this.isNew())
435	            .append("lastName", this.getLastName())
436	            .append("firstName", this.getFirstName())
437	            .append("address", this.address)
438	            .append("city", this.city)
439	            .append("telephone", this.telephone)
440	            .toString();
441	    }
442	}
